"""Restore the frozen answer candidate v2 after rejecting candidate v3.

This rollback is intentionally hash-guarded and self-contained.

It will proceed only if:
- the active runtime is exactly candidate v3;
- the frozen candidate-v2 record is unchanged;
- the embedded v2 source hashes to the frozen v2 runtime SHA.

It modifies only:
    app/api/routes/ask.py

It does NOT:
- modify evaluation artifacts;
- call models, retrieval, embeddings, or reranking;
- write to the database.

Run from backend/:
    uv run python -m py_compile scripts/restore_answer_candidate_v2.py
    uv run python -m scripts.restore_answer_candidate_v2
"""

from __future__ import annotations

import base64
import hashlib
import json
import os
from pathlib import Path


BACKEND_DIR = Path(__file__).resolve().parent.parent

RUNTIME_PATH = (
    BACKEND_DIR
    / "app"
    / "api"
    / "routes"
    / "ask.py"
)

FREEZE_PATH = (
    BACKEND_DIR
    / "tests"
    / "answer_candidate_v2_freeze.json"
)

EXPECTED_CURRENT_V3_SHA256 = (
    "F1F17F3C714C956239E4A16BAE48EB8"
    "CFFAA2BB7D7BE809EB182F7D936B008EB"
)

EXPECTED_V2_SHA256 = (
    "FF879300C09B195681E109E5B4F5D807"
    "C89216E986AE4AA9338B104FA99AAD0E"
)

EXPECTED_V2_FREEZE_SHA256 = (
    "0600D79FFC375C7CC8FC358722EE51A9"
    "8B0D979188F61FF8B4CBD7412A1CB03C"
)

V2_SOURCE_B64 = (
    ""
)


def sha256_bytes(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest().upper()


def sha256(path: Path) -> str:
    return sha256_bytes(path.read_bytes())


def main() -> None:
    if not RUNTIME_PATH.exists():
        raise SystemExit(
            f"Runtime ask.py not found: {RUNTIME_PATH}"
        )

    if not FREEZE_PATH.exists():
        raise SystemExit(
            f"Candidate-v2 freeze artifact not found: {FREEZE_PATH}"
        )

    runtime_sha = sha256(RUNTIME_PATH)

    if runtime_sha == EXPECTED_V2_SHA256:
        raise SystemExit(
            "Runtime ask.py already matches frozen candidate v2.\n"
            "No rollback performed."
        )

    if runtime_sha != EXPECTED_CURRENT_V3_SHA256:
        raise SystemExit(
            "Active runtime is not the candidate-v3 source expected "
            "for this rollback.\n"
            f"Expected: {EXPECTED_CURRENT_V3_SHA256}\n"
            f"Actual:   {runtime_sha}\n"
            "Refusing rollback."
        )

    freeze_sha = sha256(FREEZE_PATH)

    if freeze_sha != EXPECTED_V2_FREEZE_SHA256:
        raise SystemExit(
            "Candidate-v2 freeze artifact SHA mismatch.\n"
            f"Expected: {EXPECTED_V2_FREEZE_SHA256}\n"
            f"Actual:   {freeze_sha}\n"
            "Refusing rollback."
        )

    freeze = json.loads(
        FREEZE_PATH.read_text(encoding="utf-8")
    )

    if freeze.get("runtime_ask_sha256") != EXPECTED_V2_SHA256:
        raise SystemExit(
            "Candidate-v2 freeze artifact does not point to the "
            "expected v2 runtime SHA.\n"
            f"Expected: {EXPECTED_V2_SHA256}\n"
            f"Recorded: {freeze.get('runtime_ask_sha256')!r}"
        )

    v2_bytes = base64.b64decode(V2_SOURCE_B64)

    embedded_sha = sha256_bytes(v2_bytes)

    if embedded_sha != EXPECTED_V2_SHA256:
        raise SystemExit(
            "Embedded candidate-v2 source SHA mismatch.\n"
            f"Expected: {EXPECTED_V2_SHA256}\n"
            f"Actual:   {embedded_sha}\n"
            "Refusing rollback."
        )

    temp_path = RUNTIME_PATH.with_name(
        RUNTIME_PATH.name + ".restore_v2_tmp"
    )

    if temp_path.exists():
        temp_path.unlink()

    try:
        temp_path.write_bytes(v2_bytes)

        if sha256(temp_path) != EXPECTED_V2_SHA256:
            raise RuntimeError(
                "Temporary restored v2 file failed SHA verification."
            )

        os.replace(temp_path, RUNTIME_PATH)

    finally:
        if temp_path.exists():
            temp_path.unlink()

    restored_sha = sha256(RUNTIME_PATH)

    if restored_sha != EXPECTED_V2_SHA256:
        raise RuntimeError(
            "Final restored runtime SHA verification failed."
        )

    print("Waypoint answer candidate v2 restore")
    print("=" * 36)
    print(f"Runtime:                   {RUNTIME_PATH}")
    print(f"Candidate-v2 freeze:       {FREEZE_PATH}")
    print()
    print(f"Previous runtime SHA256:   {EXPECTED_CURRENT_V3_SHA256}")
    print(f"Frozen v2 SHA256:          {EXPECTED_V2_SHA256}")
    print(f"Restored runtime SHA256:   {restored_sha}")
    print(f"V2 freeze SHA256:          {freeze_sha}")
    print()
    print("Replacement type:          BYTE-FOR-BYTE")
    print("Evaluation files modified: NONE")
    print("Runtime/model calls:       NONE")
    print("Retrieval/reranker calls:  NONE")
    print("Database writes:           NONE")
    print()
    print("Answer candidate v2 restore: PASS")


if __name__ == "__main__":
    main()
